import XCTest

final class SearchFeedsTests: XCTestCase {

    func testSearchNewsAndShowFeeds() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 5) {
            openButton.tap()
        }

        bluesky.activate()
        XCTAssertTrue(bluesky.wait(for: .runningForeground, timeout: 20))
        sleep(2)

        let searchTab = bluesky.tabBars.buttons["Search"].firstMatch
        if searchTab.waitForExistence(timeout: 10) {
            searchTab.tap()
        } else {
            bluesky.buttons["Search"].firstMatch.tap()
        }
        sleep(2)

        let searchField = bluesky.searchFields.firstMatch
        if searchField.waitForExistence(timeout: 10) {
            searchField.tap()
        } else {
            bluesky.textFields.firstMatch.tap()
        }
        sleep(1)
        bluesky.typeText("news")
        sleep(1)

        let returnKey = bluesky.keyboards.buttons["Search"].firstMatch
        if returnKey.waitForExistence(timeout: 3) {
            returnKey.tap()
        } else {
            bluesky.keyboards.buttons["return"].firstMatch.tap()
        }
        sleep(3)

        let feedsTab = bluesky.buttons["Feeds"].firstMatch
        XCTAssertTrue(feedsTab.waitForExistence(timeout: 15), "Feeds tab not found: \(bluesky.debugDescription)")
        feedsTab.tap()
        sleep(3)
    }
}

