import XCTest

final class SearchFeedsTests: XCTestCase {

    func testSearchNewsAndShowFeeds() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        var dismissed = false
        for _ in 0..<15 {
            let candidates = [springboard.alerts.buttons["Open"], springboard.sheets.buttons["Open"], springboard.buttons["Open"]]
            if let btn = candidates.first(where: { $0.exists }) {
                btn.tap()
                dismissed = true
                break
            }
            sleep(1)
        }
        print("DIAG dismissed=\(dismissed)")
        if !dismissed {
            print("DIAG springboard: \(springboard.debugDescription)")
        }

        bluesky.activate()
        XCTAssertTrue(bluesky.wait(for: .runningForeground, timeout: 20))
        sleep(2)

        let searchTab = bluesky.tabBars.buttons["Search"].firstMatch
        if searchTab.waitForExistence(timeout: 10) {
            searchTab.tap()
        } else {
            bluesky.buttons["Search"].firstMatch.tap()
        }
        sleep(2)

        let searchField = bluesky.searchFields.firstMatch
        if searchField.waitForExistence(timeout: 10) {
            searchField.tap()
        } else {
            bluesky.textFields.firstMatch.tap()
        }
        sleep(1)
        bluesky.typeText("news")
        sleep(1)

        let returnKey = bluesky.keyboards.buttons["Search"].firstMatch
        if returnKey.waitForExistence(timeout: 3) {
            returnKey.tap()
        } else {
            bluesky.keyboards.buttons["return"].firstMatch.tap()
        }
        sleep(3)

        print("DIAG after search: \(bluesky.debugDescription)")

        let onScreen = bluesky.buttons.matching(NSPredicate(format: "label == 'Feeds'")).allElementsBoundByIndex
            .filter { $0.exists && $0.frame.minX >= 0 && $0.frame.width > 0 }
        print("DIAG feeds candidates: \(onScreen.map { "\($0.frame) \($0.identifier)" })")
        guard let feedsTab = onScreen.first else {
            XCTFail("No on-screen Feeds tab")
            return
        }
        feedsTab.tap()
        sleep(3)
        print("DIAG final: \(bluesky.debugDescription)")
    }
}

